    schema_ok    = { param ($c) $c -match '(?s)def\s+ratio\s*\([^)]*\)\s*:.*' -and $c -match 'round\(' -and $c -match '/\s*total' }
    empty_guard  = { param ($c) $c -match '(total\s*(==|<=|!=|<)\s*0|total\s*<=?\s*0\s*:|total\s+in\s+\(None|len\(' }
    one_block    = { param ($c) ([regex]::Matches($c, '```')).Count -ge 1 -and ([regex]::Matches($c, '```')).Count -le 4 }
  }
  P2_powershell = @{
    no_unix      = { param ($c) $c -notmatch '\b(grep|head)\b' }
    uses_rg_or_ss= { param ($c) $c -match 'Select-String' }
    recurse      = { param ($c) $c -match 'Recurse|-r\b' }
    one_ps_block = { param ($c) ([regex]::Matches($c, '```powershell')).Count -ge 1 }
  }
  P3_toolargs = @{
    json_parses  = { param ($c) try { ($c | Select-String -Pattern '\{.*"name".*"arguments".*\}' -AllMatches).Matches.Count -ge 1 } catch { $false } }
    has_fields   = { param ($c) $c -match '"query"\s*:\s*"timeout"' -and $c -match '"recursive"\s*:\s*true' }
    single_call  = { param ($c) ([regex]::Matches($c, '"name"\s*:\s*"search_repo"')).Count -eq 1 }
  }
}

$rows = foreach ($r in $data) {
  $g = $grade[$r.prompt]
  $content = [string]$r.content
  $scores = @{}
  if ($g) {
    foreach ($k in $g.Keys) {
      $fn = $g[$k]
      try { $scores[$k] = [bool](& $fn $content) } catch { $scores[$k] = $false }
    }
  }
  $total = if ($scores.Count) { ($scores.Values | Where-Object { $_ }).Count } else { 0 }
  $max   = if ($scores.Count) { $scores.Count } else { 0 }
  [pscustomobject]@{
    Prompt = $r.prompt
    Run    = $r.run
    LatSec = $r.latency_s
    TotalTokens = $r.total_tokens
    Score  = "$total / $max"
    Details = ($scores.GetEnumerator() | ForEach-Object { '{0}={1}' -f $_.Key, $_.Value }) -join ' | '
    Content = $content
  }
}

$rows | Format-Table Prompt, Run, LatSec, TotalTokens, Score -AutoSize | Out-String -Width 200
