"""A from-scratch decoder-only Transformer used by Phase A.

Pure PyTorch, no third-party model code. The implementation is intentionally
small so the algorithm itself stays auditable in one file. The point of this
module is not to compete with HuggingFace but to let the lab show that the
author can implement the bits transformers are made of, including the causal
mask, KV-friendly attention, and a deterministic checkpoint contract.
"""

from __future__ import annotations

import math
from collections.abc import Iterable
from dataclasses import asdict, dataclass

import torch
from torch import Tensor, nn


@dataclass(frozen=True)
class TinyGptConfig:
    vocab_size: int = 259
    block_size: int = 256
    n_layer: int = 4
    n_head: int = 4
    n_embd: int = 256
    dropout: float = 0.1
    pad_id: int = 0
    bos_id: int = 1
    eos_id: int = 2
    tie_weights: bool = True

    def to_dict(self) -> dict[str, object]:
        return asdict(self)

    @classmethod
    def from_dict(cls, value: dict[str, object]) -> "TinyGptConfig":
        return cls(**{key: value[key] for key in (
            "vocab_size", "block_size", "n_layer", "n_head", "n_embd", "dropout",
            "pad_id", "bos_id", "eos_id", "tie_weights",
        )})


class CausalSelfAttention(nn.Module):
    def __init__(self, n_embd: int, n_head: int, dropout: float, block_size: int) -> None:
        super().__init__()
        if n_embd % n_head != 0:
            raise ValueError("n_embd must be divisible by n_head")
        self.n_head = n_head
        self.n_embd = n_embd
        self.qkv = nn.Linear(n_embd, 3 * n_embd, bias=True)
        self.proj = nn.Linear(n_embd, n_embd, bias=True)
        self.dropout = nn.Dropout(dropout)
        self.register_buffer("causal_mask", torch.triu(torch.ones(block_size, block_size, dtype=torch.bool), diagonal=1), persistent=False)

    def forward(self, x: Tensor) -> Tensor:
        batch, time, channels = x.shape
        qkv = self.qkv(x).reshape(batch, time, 3, self.n_head, channels // self.n_head)
        q, k, v = qkv.permute(2, 0, 3, 1, 4)
        scale = 1.0 / math.sqrt(k.size(-1))
        scores = (q @ k.transpose(-2, -1)) * scale
        mask = self.causal_mask[:time, :time]
        scores = scores.masked_fill(mask, float("-inf"))
        weights = scores.softmax(dim=-1)
        weights = self.dropout(weights)
        out = (weights @ v).transpose(1, 2).reshape(batch, time, channels)
        return self.proj(out)


class Block(nn.Module):
    def __init__(self, cfg: TinyGptConfig) -> None:
        super().__init__()
        self.ln1 = nn.LayerNorm(cfg.n_embd)
        self.attn = CausalSelfAttention(cfg.n_embd, cfg.n_head, cfg.dropout, cfg.block_size)
        self.ln2 = nn.LayerNorm(cfg.n_embd)
        self.mlp = nn.Sequential(
            nn.Linear(cfg.n_embd, 4 * cfg.n_embd),
            nn.GELU(),
            nn.Linear(4 * cfg.n_embd, cfg.n_embd),
            nn.Dropout(cfg.dropout),
        )

    def forward(self, x: Tensor) -> Tensor:
        x = x + self.attn(self.ln1(x))
        x = x + self.mlp(self.ln2(x))
        return x


class TinyGpt(nn.Module):
    def __init__(self, cfg: TinyGptConfig) -> None:
        super().__init__()
        self.cfg = cfg
        self.tok_emb = nn.Embedding(cfg.vocab_size, cfg.n_embd, padding_idx=cfg.pad_id)
        self.pos_emb = nn.Embedding(cfg.block_size, cfg.n_embd)
        self.blocks = nn.ModuleList([Block(cfg) for _ in range(cfg.n_layer)])
        self.ln_f = nn.LayerNorm(cfg.n_embd)
        self.head = nn.Linear(cfg.n_embd, cfg.vocab_size, bias=False)
        if cfg.tie_weights:
            self.head.weight = self.tok_emb.weight
        self.apply(self._init_weights)

    def _init_weights(self, module: nn.Module) -> None:
        if isinstance(module, nn.Linear):
            nn.init.normal_(module.weight, mean=0.0, std=0.02)
            if module.bias is not None:
                nn.init.zeros_(module.bias)
        elif isinstance(module, nn.Embedding):
            nn.init.normal_(module.weight, mean=0.0, std=0.02)

    def forward(self, input_ids: Tensor, labels: Tensor | None = None) -> dict[str, Tensor]:
        batch, time = input_ids.shape
        if time > self.cfg.block_size:
            raise ValueError("sequence longer than block_size")
        positions = torch.arange(time, device=input_ids.device)
        x = self.tok_emb(input_ids) + self.pos_emb(positions)[None, :, :]
        for block in self.blocks:
            x = block(x)
        x = self.ln_f(x)
        logits = self.head(x)
        loss: Tensor | None = None
        if labels is not None:
            loss = nn.functional.cross_entropy(
                logits.reshape(-1, logits.size(-1)),
                labels.reshape(-1),
                ignore_index=-100,
            )
        return {"logits": logits, "loss": loss}

    @torch.no_grad()
    def generate(self, prompt_ids: Tensor, *, max_new: int, temperature: float = 0.0) -> Tensor:
        self.eval()
        was_training = self.training
        self.train(False)
        try:
            ids = prompt_ids
            finished = torch.zeros(prompt_ids.size(0), dtype=torch.bool, device=prompt_ids.device)
            for _ in range(max_new):
                cropped = ids[:, -self.cfg.block_size :]
                out = self.forward(cropped)
                logits = out["logits"][:, -1, :]
                if temperature <= 0.0:
                    next_id = logits.argmax(dim=-1, keepdim=True)
                else:
                    logits = logits / temperature
                    probs = logits.softmax(dim=-1)
                    next_id = torch.multinomial(probs, num_samples=1)
                ids = torch.cat([ids, next_id], dim=1)
                finished |= next_id.squeeze(-1).eq(self.cfg.eos_id)
                if bool(finished.all()):
                    break
            return ids
        finally:
            self.train(was_training)

    def num_parameters(self) -> int:
        return sum(parameter.numel() for parameter in self.parameters() if parameter.requires_grad)

    def save_checkpoint(self, path, *, optimizer: torch.optim.Optimizer | None = None, step: int = 0, extra: dict[str, object] | None = None) -> None:
        state = {
            "model": self.state_dict(),
            "config": self.cfg.to_dict(),
            "step": step,
            "extra": extra or {},
        }
        if optimizer is not None:
            state["optimizer"] = optimizer.state_dict()
        torch.save(state, path)

    @classmethod
    def load_checkpoint(cls, path, *, map_location: str = "cpu") -> tuple["TinyGpt", dict[str, object]]:
        state = torch.load(path, map_location=map_location, weights_only=False)
        cfg = TinyGptConfig.from_dict(state["config"])
        model = cls(cfg)
        model.load_state_dict(state["model"])
        return model, state


def iter_trainable(model: nn.Module) -> Iterable[nn.Parameter]:
    return (parameter for parameter in model.parameters() if parameter.requires_grad)
