$ErrorActionPreference = 'Stop'
$path = Get-ChildItem .\logs\adhoc_compare -Filter 'adhoc_compare_*.json' | Sort-Object LastWriteTime -Descending | Select-Object -First 1
$data = Get-Content -Raw $path.FullName | ConvertFrom-Json

# Extract the visible final answer: strip <think>...</think> reasoning if present, then take the last fenced block.
function Get-FinalAnswer($c) {
  $t = [string]$c
  $t = [regex]::Replace($t, '(?s)<think>.*?</think>', '')
  $t = [regex]::Replace($t, '(?s)<reasoning>.*?</reasoning>', '')
  $matches = [regex]::Matches($t, '```(?:\w+)?\s*\n([\s\S]*?)\n```')
  if ($matches.Count -gt 0) {
    return ($matches[$matches.Count - 1].Groups[1].Value).Trim()
  }
  # No fence: return last non-empty paragraph (skip pure prose)
  $lines = ($t -split "`n") | Where-Object { $_.Trim() -ne '' }
  return ($lines | Select-Object -Last 3) -join "`n"
}

foreach ($r in $data) {
  $fa = Get-FinalAnswer $r.content
  Write-Host ""
  Write-Host ("========== {0} | {1} | {2:F2}s | tokens={3} ==========" -f $r.prompt, $r.run, $r.latency_s, $r.total_tokens)
  Write-Host $fa
}

